<script setup lang="ts">
import { RouteOutcomeSchema } from '../../../../packages/contracts/src/observability';
import { RunSummarySchema } from '../../../../packages/contracts/src/index';
import { agentStatusLabels, routeOutcomeLabels, type RecordFilters } from './observability-model';
const filters=defineModel<RecordFilters>({required:true});
defineProps<{kind:'route'|'agent';busy:boolean;platforms:readonly {id:string;label:string}[];agents:readonly {id:string;label:string}[]}>();
defineEmits<{apply:[];reset:[]}>();
</script>
<template><form class="record-filters" @submit.prevent="$emit('apply')"><label>平台实例<select v-model="filters.platform" :disabled="busy"><option value="">全部平台</option><option v-if="filters.platform&&!platforms.some(item=>item.id===filters.platform)" :value="filters.platform">{{filters.platform}}</option><option v-for="item in platforms" :key="item.id" :value="item.id">{{item.label}}</option></select></label><label>会话类型<select v-model="filters.sessionType" :disabled="busy"><option value="">群聊与私聊</option><option value="group">仅群聊</option><option value="private">仅私聊</option></select></label><label>Agent<select v-model="filters.agentId" :disabled="busy"><option value="">全部 Agent</option><option v-if="filters.agentId&&!agents.some(item=>item.id===filters.agentId)" :value="filters.agentId">{{filters.agentId}}</option><option v-for="item in agents" :key="item.id" :value="item.id">{{item.label}}</option></select></label><label v-if="kind==='route'">路由结果<select v-model="filters.outcome" :disabled="busy"><option value="">全部结果</option><option v-for="value in RouteOutcomeSchema.options" :key="value" :value="value">{{routeOutcomeLabels[value]}}</option></select></label><label v-else>执行状态<select v-model="filters.status" :disabled="busy"><option value="">全部状态</option><option v-for="value in RunSummarySchema.shape.status.options" :key="value" :value="value">{{agentStatusLabels[value]}}</option></select></label><label>会话 ID<input v-model="filters.sessionId" :disabled="busy" placeholder="精确匹配会话 ID"/></label><label>关键词<input v-model="filters.search" :disabled="busy" placeholder="搜索记录内容"/></label><details><summary>时间范围</summary><p>使用浏览器所在时区。</p><label>开始时间<input v-model="filters.from" type="datetime-local" :disabled="busy"/></label><label>结束时间<input v-model="filters.to" type="datetime-local" :disabled="busy"/></label></details><div class="record-filter-actions"><button type="submit" :disabled="busy">查询</button><button type="button" :disabled="busy" @click="$emit('reset')">清空筛选</button></div></form></template>
<style scoped>.record-filters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;align-items:end}.record-filters label{display:grid;gap:6px;font-size:12px}.record-filters input,.record-filters select{width:100%;font-size:13px;min-width:0}.record-filters details{font-size:12px;align-self:start;padding-top:25px}.record-filters details>label{margin-top:10px}.record-filters summary{cursor:pointer;color:var(--muted)}.record-filter-actions{display:flex;gap:8px;flex-wrap:wrap}.record-filter-actions button{font-size:12px}.record-filter-actions>button:first-child{background:var(--accent);border-color:var(--accent);color:white}@media(max-width:900px){.record-filters{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:500px){.record-filters{grid-template-columns:1fr 1fr}.record-filter-actions{grid-column:1/-1}.record-filters details{padding-top:0}}</style>
